import{_ as a,o as e,c as i,a2 as n}from"./chunks/framework.Ddyno5UB.js";const u=JSON.parse('{"title":"3. User & Group Management","description":"","frontmatter":{},"headers":[],"relativePath":"linux/user-management.md","filePath":"linux/user-management.md"}'),t={name:"linux/user-management.md"};function o(l,s,r,p,d,h){return e(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="_3-user-group-management" tabindex="-1">3. User &amp; Group Management <a class="header-anchor" href="#_3-user-group-management" aria-label="Permalink to &quot;3. User &amp; Group Management&quot;">​</a></h1><p>Linux is a multi-user system. Managing who has access to what is the foundation of system security.</p><h2 id="core-configuration-files" tabindex="-1">Core Configuration Files <a class="header-anchor" href="#core-configuration-files" aria-label="Permalink to &quot;Core Configuration Files&quot;">​</a></h2><p>Three main files manage users and groups in Linux:</p><ol><li><strong><code>/etc/passwd</code></strong>: Contains a list of all users, their User IDs (UIDs), Group IDs (GIDs), home directories, and default shells. It does <em>not</em> contain passwords.</li><li><strong><code>/etc/shadow</code></strong>: Contains the securely hashed passwords for users. It is readable only by root.</li><li><strong><code>/etc/group</code></strong>: Contains a list of all groups and which users belong to them.</li></ol><h2 id="managing-users" tabindex="-1">Managing Users <a class="header-anchor" href="#managing-users" aria-label="Permalink to &quot;Managing Users&quot;">​</a></h2><h3 id="adding-a-user" tabindex="-1">Adding a User <a class="header-anchor" href="#adding-a-user" aria-label="Permalink to &quot;Adding a User&quot;">​</a></h3><p>Use <code>useradd</code> (or the interactive <code>adduser</code> on Debian-based systems) to create a new user account.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Add a user with a home directory and bash shell</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> useradd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /bin/bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span></code></pre></div><h3 id="modifying-a-user" tabindex="-1">Modifying a User <a class="header-anchor" href="#modifying-a-user" aria-label="Permalink to &quot;Modifying a User&quot;">​</a></h3><p>Use <code>usermod</code> to modify properties like appending a user to a group.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Add &#39;alice&#39; to the &#39;docker&#39; group (-aG means append group)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usermod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -aG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span></code></pre></div><h3 id="passwords" tabindex="-1">Passwords <a class="header-anchor" href="#passwords" aria-label="Permalink to &quot;Passwords&quot;">​</a></h3><p>Set or change a user&#39;s password using <code>passwd</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> passwd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span></code></pre></div><h2 id="privilege-escalation" tabindex="-1">Privilege Escalation <a class="header-anchor" href="#privilege-escalation" aria-label="Permalink to &quot;Privilege Escalation&quot;">​</a></h2><p>Directly logging in as the root user is considered bad practice. Instead, regular users are granted administrative privileges using <code>sudo</code> (Super User DO).</p><h3 id="the-sudoers-file" tabindex="-1">The Sudoers File <a class="header-anchor" href="#the-sudoers-file" aria-label="Permalink to &quot;The Sudoers File&quot;">​</a></h3><p>The <code>/etc/sudoers</code> file defines exactly which users and groups can run commands as root.</p><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>Never edit <code>/etc/sudoers</code> directly with a text editor like vim or nano. A syntax error can lock you out of root access permanently. <strong>Always use <code>visudo</code>.</strong></p></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Safely edit the sudoers file</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> visudo</span></span></code></pre></div><p>Common entries in the sudoers file look like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Allow the user &#39;alice&#39; to run any command</span></span>
<span class="line"><span>alice   ALL=(ALL:ALL) ALL</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Allow members of the &#39;%wheel&#39; group to run any command</span></span>
<span class="line"><span>%wheel  ALL=(ALL:ALL) ALL</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Allow user &#39;bob&#39; to restart Nginx without a password</span></span>
<span class="line"><span>bob     ALL=(ALL) NOPASSWD: /bin/systemctl restart nginx</span></span></code></pre></div><h3 id="switching-users-su" tabindex="-1">Switching Users (<code>su</code>) <a class="header-anchor" href="#switching-users-su" aria-label="Permalink to &quot;Switching Users (\`su\`)&quot;">​</a></h3><p>To temporarily switch to another user session in your terminal, use <code>su</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Switch to root (requires root password)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">su</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Switch to alice (if you are root, no password needed)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">su</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span></code></pre></div>`,26)])])}const g=a(t,[["render",o]]);export{u as __pageData,g as default};
